import sys

mod = 1000000007

def main():
    input_value = sys.stdin.read().strip()
    n = int(input_value)
    max_size = 2005
    dp = [[0] * max_size for _ in range(max_size)]
    ok = [[0] * max_size for _ in range(max_size)]
    ok[0][0] = 1
    for i in range(1, 2001 + 1):
        for j in range(i & 1, i + 1, 2):
            if j == 0:
                dp[i][j] = dp[i - 1][j + 1]
                if ok[i - 1][j + 1] == 1:
                    dp[i][j] = (dp[i][j] + 1) % mod
                else:
                    ok[i][j] = 1
                continue
            dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j + 1]) % mod
            if ok[i - 1][j + 1] == 1 or ok[i - 1][j - 1] == 1:
                dp[i][j] = (dp[i][j] + 1) % mod
            else:
                ok[i][j] = 1
    print(dp[2 * n][0])

if __name__ == "__main__":
    main()

